import React, { useMemo } from 'react';
import { CARS } from '../../constants';
import { calculatePaymentBreakdown } from '../../utils/dashboardCalculator';

const DailyIncomeTable = ({ dailyIncome, handleDelete }) => {
  const { totals, groupedByDate } = useMemo(() => {
    let tCash = 0, tCard = 0, tPrePaid = 0, tGcc = 0, tNonGcc = 0, tAll = 0;
    const sortedList = [...(dailyIncome || [])].sort((a, b) => new Date(b.date) - new Date(a.date));

    // Group by date
    const grouped = {};
    sortedList.forEach(e => {
      const breakdown = calculatePaymentBreakdown(e);
      tCash += breakdown.cash;
      tCard += breakdown.card;
      tPrePaid += breakdown.prePaid;
      tGcc += breakdown.gcc;
      tNonGcc += breakdown.nonGcc;
      tAll += breakdown.total;

      if (!grouped[e.date]) {
        grouped[e.date] = {
          entries: [],
          subtotal: { cash: 0, card: 0, prePaid: 0, gcc: 0, nonGcc: 0, total: 0 }
        };
      }
      grouped[e.date].entries.push({ ...e, _breakdown: breakdown });
      grouped[e.date].subtotal.cash += breakdown.cash;
      grouped[e.date].subtotal.card += breakdown.card;
      grouped[e.date].subtotal.prePaid += breakdown.prePaid;
      grouped[e.date].subtotal.gcc += breakdown.gcc;
      grouped[e.date].subtotal.nonGcc += breakdown.nonGcc;
      grouped[e.date].subtotal.total += breakdown.total;
    });

    // Convert to array and sort dates (latest first)
    const dateGroups = Object.keys(grouped).sort((a, b) => new Date(b) - new Date(a));

    return {
      totals: { tCash, tCard, tPrePaid, tGcc, tNonGcc, tAll },
      groupedByDate: { grouped, dateGroups }
    };
  }, [dailyIncome]);

  if (!dailyIncome || dailyIncome.length === 0) return <p className="muted">No daily income records yet.</p>;

  return (
    <div className="table-responsive">
      <table className="table striped">
        <thead>
          <tr>
            <th>Date</th>
            <th>Car</th>
            <th className="text-right">Cash</th>
            <th className="text-right">Card</th>
            <th className="text-right">Pre Paid</th>
            <th className="text-right">GCC</th>
            <th className="text-right">Non-GCC</th>
            <th className="text-right">Total</th>
            <th className="text-center">Actions</th>
          </tr>
        </thead>
        <tbody>
          {groupedByDate.dateGroups.map((date) => {
            const group = groupedByDate.grouped[date];
            return (
              <React.Fragment key={date}>
                {group.entries.map((item) => (
                  <tr key={item.id}>
                    <td>{item.date}</td>
                    <td>{CARS[item.car]?.label || item.car}</td>
                    <td className="text-right">£{item._breakdown.cash.toFixed(2)}</td>
                    <td className="text-right">£{item._breakdown.card.toFixed(2)}</td>
                    <td className="text-right">£{item._breakdown.prePaid.toFixed(2)}</td>
                    <td className="text-right">£{item._breakdown.gcc.toFixed(2)}</td>
                    <td className="text-right">£{item._breakdown.nonGcc.toFixed(2)}</td>
                    <td className="text-right font-bold">£{item._breakdown.total.toFixed(2)}</td>
                    <td className="text-center">
                      <button
                        className="btn-icon danger"
                        onClick={() => handleDelete('income', dailyIncome.indexOf(dailyIncome.find(orig => orig.id === item.id)))}
                        title="Delete"
                      >
                        🗑
                      </button>
                    </td>
                  </tr>
                ))}
                {/* Date Subtotal Row */}
                <tr style={{ background: 'var(--bg-tertiary)', borderTop: '2px solid var(--border)', borderBottom: '2px solid var(--border)' }}>
                  <td colSpan="2" className="font-bold" style={{ fontStyle: 'italic' }}>
                    {date} Subtotal
                  </td>
                  <td className="text-right font-bold">£{group.subtotal.cash.toFixed(2)}</td>
                  <td className="text-right font-bold">£{group.subtotal.card.toFixed(2)}</td>
                  <td className="text-right font-bold">£{group.subtotal.prePaid.toFixed(2)}</td>
                  <td className="text-right font-bold">£{group.subtotal.gcc.toFixed(2)}</td>
                  <td className="text-right font-bold">£{group.subtotal.nonGcc.toFixed(2)}</td>
                  <td className="text-right font-bold">£{group.subtotal.total.toFixed(2)}</td>
                  <td></td>
                </tr>
              </React.Fragment>
            );
          })}
        </tbody>
        <tfoot>
          <tr className="font-bold" style={{ background: 'var(--bg-secondary)' }}>
            <td colSpan="2">GRAND TOTAL</td>
            <td className="text-right">£{totals.tCash.toFixed(2)}</td>
            <td className="text-right">£{totals.tCard.toFixed(2)}</td>
            <td className="text-right">£{totals.tPrePaid.toFixed(2)}</td>
            <td className="text-right">£{totals.tGcc.toFixed(2)}</td>
            <td className="text-right">£{totals.tNonGcc.toFixed(2)}</td>
            <td className="text-right">£{totals.tAll.toFixed(2)}</td>
            <td></td>
          </tr>
        </tfoot>
      </table>
    </div>
  );
};

export default DailyIncomeTable;