import React from 'react';

const AnnualExpenseTable = ({ annualExpenses, handleDelete }) => {
    return (
        <div className="table-container">
            <table>
                <thead>
                    <tr>
                        <th>Year</th>
                        <th>Car</th>
                        <th>Type</th>
                        <th>Amount (£)</th>
                        <th className="no-print">Actions</th>
                    </tr>
                </thead>
                <tbody>
                    {annualExpenses.length > 0 ? (
                        annualExpenses.map((expense, index) => (
                            <tr key={index}>
                                <td>{expense.year}</td>
                                <td>{expense.car === 'ALL' ? 'All Taxis' : expense.car}</td>
                                <td>{expense.type}</td>
                                <td>{Number(expense.amount).toFixed(2)}</td>
                                <td className="no-print">
                                    <button
                                        className="btn alt danger"
                                        onClick={() => handleDelete('annual', index)}
                                        style={{ padding: '4px 8px', fontSize: '0.75rem' }}
                                    >
                                        Delete
                                    </button>
                                </td>
                            </tr>
                        ))
                    ) : (
                        <tr>
                            <td colSpan="5" style={{ textAlign: 'center' }} className="muted">
                                No annual expenses recorded.
                            </td>
                        </tr>
                    )}
                </tbody>
            </table>
        </div>
    );
};

export default AnnualExpenseTable;
