
import React, { useMemo, useState } from 'react';
import { calculateAnnualReport } from '../../utils/dashboardCalculator';

const AnnualReport = ({ dailyIncome, weeklyRentals, dailyFuel, monthlyExpenses, annualExpenses, mileage, otherExpenses, selectedYear }) => {
    const [reportStatus, setReportStatus] = useState(null);

    const handleGenerate = () => {
        if (!reportData || reportData.noData) {
            setReportStatus({ type: 'warning', message: 'No data available for the selected year.' });
            setTimeout(() => setReportStatus(null), 3000);
            return;
        }
        setReportStatus({ type: 'success', message: 'Annual Report generated successfully!' });
        setTimeout(() => setReportStatus(null), 3000);
    };

    const handleExport = () => {
        const isMobile = /Android|webOS|iPhone|iPad|iPod/i.test(navigator.userAgent);

        if (isMobile && navigator.share) {
            const shareText = generateShareText();
            navigator.share({
                title: `Annual Report - ${selectedYear} `,
                text: shareText,
            }).catch(() => window.print());
        } else {
            window.print();
        }
    };

    const generateShareText = () => {
        if (!reportData) return '';
        const { income, totalProfit, totalMileage, totalOtherExpenses } = reportData;
        const totalIncome = income.SG24ZSN + income.NU75DXB + income.LL68RRX;
        return `📊 Annual Report: ${selectedYear} \n\n` +
            `💰 Total Income: £${totalIncome.toLocaleString(undefined, { minimumFractionDigits: 2 })} \n` +
            (totalMileage > 0 ? `🚗 Total Distance: ${totalMileage.toLocaleString()} miles\n` : '') +
            (totalOtherExpenses > 0 ? `📋 Other Expenses: £${totalOtherExpenses.toFixed(2)} \n` : '') +
            `\n📈 Annual Profit: £${totalProfit.toLocaleString(undefined, { minimumFractionDigits: 2 })} `;
    };

    const reportData = useMemo(() => {
        return calculateAnnualReport({
            dailyIncome, weeklyRentals, dailyFuel, monthlyExpenses, annualExpenses, mileage, otherExpenses
        }, selectedYear);
    }, [dailyIncome, weeklyRentals, dailyFuel, monthlyExpenses, annualExpenses, mileage, otherExpenses, selectedYear]);

    if (!selectedYear || !reportData) {
        return <p className="muted">Select a year to view the annual report.</p>;
    }

    const { income, fuel, expenses, totalProfit, totalMileage, mileageByTaxi, totalOtherExpenses, noData } = reportData;

    const renderRow = (id, name) => {
        const p = income[id] - fuel[id] - expenses[id];
        return (
            <tr key={id}>
                <td>{name}</td>
                <td>£{income[id].toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                <td>£{fuel[id].toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                <td>£{expenses[id].toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                <td className={p >= 0 ? 'success' : 'danger'}>£{p.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
            </tr>
        );
    };

    return (
        <div className="report-container">
            <div className="card">
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
                    <h3 style={{ margin: 0 }}>Annual Business Performance: {selectedYear}</h3>
                    <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
                        {reportStatus && (
                            <span style={{
                                padding: '6px 12px',
                                borderRadius: '6px',
                                fontSize: '0.85rem',
                                fontWeight: '500',
                                background: reportStatus.type === 'success' ? 'var(--success-bg)' : 'var(--warn-bg)',
                                color: reportStatus.type === 'success' ? 'var(--success-text)' : 'var(--warn-text)',
                                animation: 'fadeIn 0.2s ease'
                            }}>
                                {reportStatus.type === 'success' ? '✓' : '⚠'} {reportStatus.message}
                            </span>
                        )}
                        <button className="btn primary" onClick={handleGenerate}>
                            🔄 Generate Report
                        </button>
                        <button className="btn alt no-print" onClick={handleExport}>
                            📤 Export/Share
                        </button>
                    </div>
                </div>

                {noData ? (
                    <div style={{
                        background: 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)',
                        border: '1px solid #f59e0b',
                        borderRadius: '8px',
                        textAlign: 'center',
                        padding: '30px'
                    }}>
                        <span style={{ fontSize: '2rem' }}>📋</span>
                        <h4 style={{ margin: '10px 0 5px', color: '#92400e' }}>No Data for This Year</h4>
                        <p className="muted" style={{ margin: 0 }}>
                            There are no entries recorded for the selected year.
                        </p>
                    </div>
                ) : (
                    <>
                        <div className="table-container">
                            <table>
                                <thead>
                                    <tr>
                                        <th>Taxi</th>
                                        <th>Total Income</th>
                                        <th>Total Fuel</th>
                                        <th>Total Expenses</th>
                                        <th>Net Profit</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {renderRow('SG24ZSN', 'Taxi A')}
                                    {renderRow('NU75DXB', 'Taxi B (Rented)')}
                                    {renderRow('LL68RRX', 'Taxi C (Rented)')}
                                    <tr style={{ background: 'var(--bg)', fontWeight: 'bold' }}>
                                        <td>TOTAL</td>
                                        <td>£{(income.SG24ZSN + income.NU75DXB + income.LL68RRX).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                                        <td>£{(fuel.SG24ZSN + fuel.NU75DXB + fuel.LL68RRX).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                                        <td>£{(expenses.SG24ZSN + expenses.NU75DXB + expenses.LL68RRX).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                                        <td className={totalProfit >= 0 ? 'success' : 'danger'}>£{totalProfit.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>

                        {/* Annual Mileage Summary */}
                        {totalMileage > 0 && (
                            <div style={{
                                background: 'linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%)',
                                border: '1px solid #10b981',
                                borderRadius: '8px',
                                padding: '15px 20px',
                                marginTop: '20px',
                                display: 'flex',
                                alignItems: 'center',
                                gap: '15px',
                                flexWrap: 'wrap'
                            }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                                    <span style={{ fontSize: '1.5rem' }}>🚗</span>
                                    <div>
                                        <div style={{ fontSize: '0.75rem', color: '#065f46', fontWeight: '600', textTransform: 'uppercase' }}>
                                            Annual Distance
                                        </div>
                                        <div style={{ fontSize: '1.5rem', fontWeight: '700', color: '#047857' }}>
                                            {totalMileage.toLocaleString()} miles
                                        </div>
                                    </div>
                                </div>
                                {Object.keys(mileageByTaxi).length > 0 && (
                                    <div style={{ marginLeft: 'auto', display: 'flex', gap: '20px' }}>
                                        {Object.entries(mileageByTaxi).map(([car, dist]) => (
                                            <div key={car} style={{ textAlign: 'center' }}>
                                                <div style={{ fontSize: '0.7rem', color: '#065f46' }}>
                                                    {car === 'SG24ZSN' ? 'Taxi A' : car === 'NU75DXB' ? 'Taxi B' : 'Taxi C'}
                                                </div>
                                                <div style={{ fontWeight: '600', color: '#047857' }}>{dist.toLocaleString()} mi</div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}

                        {/* Other Expenses Note */}
                        {totalOtherExpenses > 0 && (
                            <div style={{
                                marginTop: '15px',
                                padding: '10px 15px',
                                background: 'rgba(239, 68, 68, 0.1)',
                                borderRadius: '8px',
                                fontSize: '0.85rem',
                                color: 'var(--danger-text)'
                            }}>
                                📋 Other Expenses included: <strong>£{totalOtherExpenses.toFixed(2)}</strong>
                            </div>
                        )}

                        <div style={{ marginTop: '30px', padding: '20px', background: 'var(--bg)', borderRadius: '12px', textAlign: 'center' }}>
                            <h2 style={{ margin: 0, color: 'var(--muted)', fontSize: '1rem', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Total Annual Profit</h2>
                            <div style={{ fontSize: '3rem', fontWeight: '800', color: totalProfit >= 0 ? 'var(--success)' : 'var(--danger)', marginTop: '5px' }}>
                                £{totalProfit.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                            </div>
                        </div>
                    </>
                )}
            </div>
        </div>
    );
};

export default AnnualReport;

