import { db, auth } from '../firebase';
import { doc, getDoc, setDoc } from "firebase/firestore";
import { localDb, getFromLocal } from './localDb';

/**
 * Super Sync Storage Utility
 * 1. Works 100% locally using Dexie (IndexedDB)
 * 2. Syncs to Firebase Cloud for "Online Backup"
 * 3. Supports Mobile & Laptop consistency
 */

const DOC_PATH = (uid) => `users/${uid}/taxi_data/management`;
const COLLECTIONS = ['dailyIncome', 'weeklyRentals', 'dailyFuel', 'monthlyExpenses', 'annualExpenses', 'mileage', 'otherExpenses'];

export const getData = async (key) => {
  // Always load from local DB first for instant speed (Million Dollar Experience)
  const localItems = await getFromLocal(key);

  // If we have local items, return them immediately
  if (localItems.length > 0) {
    return localItems;
  }

  // If local is empty, try to fetch from Cloud Backup
  const user = auth.currentUser;
  if (user) {
    try {
      const docRef = doc(db, DOC_PATH(user.uid));
      const docSnap = await getDoc(docRef);
      if (docSnap.exists()) {
        const cloudData = docSnap.data()[key] || [];
        // Save cloud data to local for next time
        for (const item of cloudData) {
          const { id, ...cleanItem } = item;
          await localDb[key].add(cleanItem);
        }
        return cloudData;
      }
    } catch (e) {
      console.warn("Cloud Backup not available:", e);
    }
  }

  return [];
};

export const saveData = async (key, data, isDelete = false) => {
  // 1. Update LOCAL Database
  await localDb[key].clear();
  for (const item of data) {
    const { id, ...rest } = item; // Don't re-save the old auto-generated ID
    await localDb[key].add(rest);
  }

  // 2. Perform ONLINE Backup in the background
  const user = auth.currentUser;
  if (user) {
    try {
      const cleanData = data.map(({ id, ...rest }) => rest);
      const docRef = doc(db, DOC_PATH(user.uid));
      await setDoc(docRef, { [key]: cleanData }, { merge: true });
    } catch (e) {
      console.warn("Cloud Backup failed. Data is still safe on your computer.", e);
    }
  }
};

export const syncAllData = async () => {
  const user = auth.currentUser;
  if (!user) return false;

  try {
    const docRef = doc(db, DOC_PATH(user.uid));
    const docSnap = await getDoc(docRef);
    const cloudAll = docSnap.exists() ? docSnap.data() : {};

    for (const key of COLLECTIONS) {
      // 1. Get Local & Cloud
      const localItems = await getFromLocal(key);
      const cloudItems = cloudAll[key] || [];

      // 2. Merge & Dedup (using JSON stringify as signature)
      const uniqueMap = new Map();

      const addToMap = (items) => {
        items.forEach(item => {
          const { id, ...dataOnly } = item;
          // Sort keys to ensure consistent stringification
          const ordered = Object.keys(dataOnly).sort().reduce(
            (obj, k) => {
              obj[k] = dataOnly[k];
              return obj;
            }, {}
          );
          uniqueMap.set(JSON.stringify(ordered), ordered);
        });
      };

      addToMap(localItems);
      addToMap(cloudItems);

      const mergedData = Array.from(uniqueMap.values());

      // 3. Update Local
      await localDb[key].clear();
      for (const item of mergedData) {
        await localDb[key].add(item);
      }

      // 4. Update Cloud (Batch effectively via the final write)
      cloudAll[key] = mergedData;
    }

    // Write all merged collections back to cloud at once
    await setDoc(docRef, cloudAll, { merge: true });
    return true;

  } catch (e) {
    console.error("Sync failed:", e);
    return false;
  }
};
