import { CARS } from '../../constants';

const MileageTable = ({ mileage, handleDelete }) => {
    if (!mileage || mileage.length === 0) return <p className="muted">No mileage records yet.</p>;
    const sorted = [...mileage].sort((a, b) => new Date(b.date) - new Date(a.date));
    const totalMileage = sorted.reduce((s, m) => s + Number(m.dailyMileage || m.distance || 0), 0);

    return (
        <div className="table-container">
            <div style={{ background: 'var(--bg)', padding: '12px', borderBottom: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between' }}>
                <span>📊 Records: {sorted.length}</span>
                <span style={{ fontWeight: '700', color: 'var(--success)' }}>Total: {totalMileage.toLocaleString()} miles</span>
            </div>
            <table>
                <thead><tr><th>Date</th><th>Car</th><th>Morning</th><th>End of Day</th><th>Daily Mileage</th><th>Status</th><th>Action</th></tr></thead>
                <tbody>
                    {sorted.map((e, i) => {
                        const origIdx = mileage.findIndex(m => m.date === e.date && m.car === e.car && (m.morningMileage ?? m.startMileage) === (e.morningMileage ?? e.startMileage));
                        const morning = e.morningMileage ?? e.startMileage ?? 0;
                        const eod = e.endOfDayMileage ?? e.endMileage ?? null;
                        const daily = e.dailyMileage ?? e.distance ?? 0;
                        const complete = eod !== null && eod > 0;
                        return (
                            <tr key={i}>
                                <td>{e.date}</td>
                                <td>{CARS[e.car]?.label?.split(' - ')[0] || e.car}</td>
                                <td>{Number(morning).toLocaleString()}</td>
                                <td>{complete ? Number(eod).toLocaleString() : <span style={{ color: 'var(--warn)' }}>Pending</span>}</td>
                                <td style={{ fontWeight: '600', color: complete ? 'var(--success)' : 'var(--muted)' }}>{complete ? `${daily.toLocaleString()} mi` : '—'}</td>
                                <td>{complete ? <span style={{ background: 'var(--success-bg)', color: 'var(--success-text)', padding: '2px 8px', borderRadius: '12px', fontSize: '0.7rem' }}>✓ Complete</span> : <span style={{ background: 'var(--warn-bg)', color: 'var(--warn-text)', padding: '2px 8px', borderRadius: '12px', fontSize: '0.7rem' }}>⏳ Pending</span>}</td>
                                <td><button className="action-btn" onClick={() => handleDelete('mileage', origIdx)}>🗑️</button></td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
        </div>
    );
};

export default MileageTable;
