import { CARS } from '../../constants';

const OtherExpensesTable = ({ otherExpenses, handleDelete }) => {
    if (!otherExpenses || otherExpenses.length === 0) {
        return <p className="muted">No other expenses recorded yet.</p>;
    }

    // Sort by date, most recent first
    const sortedExpenses = [...otherExpenses].sort((a, b) => new Date(b.date) - new Date(a.date));

    return (
        <div className="table-container">
            <table>
                <thead>
                    <tr>
                        <th>Date</th>
                        <th>Car</th>
                        <th>Type</th>
                        <th>Description</th>
                        <th>Amount</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    {sortedExpenses.map((expense, index) => {
                        // Find the original index for delete
                        const originalIndex = otherExpenses.findIndex(e =>
                            e.date === expense.date &&
                            e.type === expense.type &&
                            e.amount === expense.amount
                        );

                        return (
                            <tr key={index}>
                                <td>{expense.date}</td>
                                <td>
                                    {expense.car === 'ALL'
                                        ? 'All'
                                        : (CARS[expense.car]?.label?.split(' - ')[0] || expense.car)}
                                </td>
                                <td>
                                    <span style={{
                                        background: 'rgba(100, 116, 139, 0.1)',
                                        padding: '3px 8px',
                                        borderRadius: '4px',
                                        fontSize: '0.8rem',
                                        fontWeight: '500'
                                    }}>
                                        {expense.type}
                                    </span>
                                </td>
                                <td style={{ maxWidth: '150px', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                    {expense.description || '-'}
                                </td>
                                <td style={{ fontWeight: '600', color: 'var(--danger)' }}>
                                    £{Number(expense.amount || 0).toFixed(2)}
                                </td>
                                <td>
                                    <button
                                        className="action-btn"
                                        onClick={() => handleDelete('otherExpense', originalIndex)}
                                        title="Delete entry"
                                    >
                                        🗑️
                                    </button>
                                </td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
        </div>
    );
};

export default OtherExpensesTable;
