const DeleteModal = ({ onCancel, onConfirm, itemType = 'record' }) => {
  // User-friendly labels for item types
  const typeLabels = {
    income: 'income entry',
    rental: 'rental entry',
    fuel: 'fuel entry',
    expense: 'expense entry',
    annual: 'annual expense',
    mileage: 'mileage entry',
    otherExpense: 'expense entry',
    record: 'record'
  };

  const label = typeLabels[itemType] || 'record';

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <div className="modal-header">
          <h3 style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <span>⚠️</span> Confirm Deletion
          </h3>
          <button className="close-btn" onClick={onCancel}>×</button>
        </div>

        <div className="modal-body">
          <p style={{ margin: '0 0 16px', color: 'var(--text)', lineHeight: '1.6' }}>
            Are you sure you want to delete this <strong>{label}</strong>?
          </p>

          <div style={{
            background: 'var(--warn-bg)',
            border: '1px solid var(--warn)',
            borderRadius: '8px',
            padding: '12px 16px',
            display: 'flex',
            gap: '10px',
            alignItems: 'flex-start'
          }}>
            <span style={{ fontSize: '1.1rem' }}>💡</span>
            <div style={{ fontSize: '0.85rem', color: 'var(--warn-text)', lineHeight: '1.5' }}>
              <strong>Tip:</strong> Use this when a customer cancels a trip, or if you entered something incorrectly.
              This action cannot be undone.
            </div>
          </div>
        </div>

        <div className="modal-actions">
          <button className="btn alt" onClick={onCancel}>
            Keep It
          </button>
          <button className="btn danger" onClick={onConfirm}>
            Yes, Delete
          </button>
        </div>
      </div>
    </div>
  );
};

export default DeleteModal;